import java.util.HashMap;
import java.util.Map;

class Solution {
    /**
     * 方法一：動態規劃（DP 陣列）
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public int climbStairs(int n) {
        if (n <= 2) {
            return n;
        }

        // dp[i] 表示到達第 i 階的方法數
        int[] dp = new int[n + 1];
        dp[1] = 1;
        dp[2] = 2;

        for (int i = 3; i <= n; i++) {
            dp[i] = dp[i-1] + dp[i-2];
        }

        return dp[n];
    }

    /**
     * 方法二：動態規劃（空間優化）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int climbStairs_optimized(int n) {
        if (n <= 2) {
            return n;
        }

        // 只需要保存前兩個狀態
        int prev2 = 1;  // dp[1]
        int prev1 = 2;  // dp[2]

        for (int i = 3; i <= n; i++) {
            int current = prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }

    /**
     * 方法三：遞迴 + 記憶化
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public int climbStairs_memo(int n) {
        Map<Integer, Integer> memo = new HashMap<>();
        return climb(n, memo);
    }

    private int climb(int n, Map<Integer, Integer> memo) {
        if (n <= 2) {
            return n;
        }

        if (memo.containsKey(n)) {
            return memo.get(n);
        }

        int result = climb(n-1, memo) + climb(n-2, memo);
        memo.put(n, result);
        return result;
    }

    /**
     * 方法四：最簡潔寫法（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int climbStairs_clean(int n) {
        if (n <= 2) {
            return n;
        }

        int a = 1, b = 2;
        for (int i = 3; i <= n; i++) {
            int temp = a + b;
            a = b;
            b = temp;
        }

        return b;
    }
}

